                layout,
                mem,
                engine: Engine::new(),
            }
        }

        /// Emit `root` (delta against the previous emit) and return the frame's
        /// slots + arena copied into owned buffers (`frame spans 0..len`).
        /// An unchanged tree emits **zero** opcodes (returns empty buffers).
        fn emit(&mut self, root: &Node) -> (Vec<u8>, Vec<u8>) {
            let layout = self.layout;
            {
                let mut guest = Guest::new(&mut self.mem, &layout);
                guest.begin_frame();
                self.engine.emit(root, &mut guest).unwrap();
                guest.end_frame();
            }
            let mut host = Host::new(&mut self.mem, &layout);
            let frames = host.frames();
            assert!(frames.len() <= 1, "at most one frame per emit");
            let Some(f) = frames.first() else {
                return (Vec::new(), Vec::new());
            };
            let mut slots = Vec::with_capacity(f.len() * 16);
            for op in f.opcodes() {
                slots.extend_from_slice(&op.to_bytes());
            }
            let arena = f.arena().to_vec();
            (slots, arena)
        }
    }

    fn apply_emit(r: &mut QtRenderer, h: &mut Harness, root: &Node) {
        let (slots, arena) = h.emit(root);
        let frame = Frame::from_parts(&slots, &arena, 0, slots.len());
        r.tree.apply_frame(&frame);
    }

    #[test]
    fn first_frame_creates_tree_and_props() {
        let mut view = vstack![text("ab"), text("cd")].with(|v| { v.spacing(4.0); }).modifiers(Padding(8.0)).build();
        assign_ids(&mut view, &mut 1);

        let mut h = Harness::new();
        let mut r = QtRenderer::new();
        apply_emit(&mut r, &mut h, &view);
        let cmds = r.diff();

        let kinds: Vec<u8> = cmds.iter().map(|c| c.kind).collect();
        // Creates for 1,2,3 then per-node reset+props/text, then children.
        assert!(kinds.contains(&Command::CREATE_NODE));
        assert!(kinds.contains(&Command::RESET_NODE));
        assert!(kinds.contains(&Command::SET_TEXT));
        assert!(kinds.contains(&Command::SET_PROPERTY));

        // Root (1) is created, reset, gets SPACING + PADDING props.
        let root_props: Vec<&Command> = cmds
            .iter()
            .filter(|c| c.kind == Command::SET_PROPERTY && c.a == 1)
            .collect();
        assert!(!root_props.is_empty());
        let spacing = root_props
            .iter()
            .any(|c| (c.b & 0xFFFF) as u16 == pathland_core::property_id::SPACING);
        assert!(spacing, "root carries SPACING");
    }

    #[test]
    fn unchanged_frame_emits_zero_commands() {
        let mut view = vstack![text("ab")].with(|v| { v.spacing(4.0); }).build();
        assign_ids(&mut view, &mut 1);
        let mut h = Harness::new();
        let mut r = QtRenderer::new();
        apply_emit(&mut r, &mut h, &view);
        let first = r.diff();
        assert!(!first.is_empty());

        // Re-emitting the same tree (same engine) changes nothing -> zero commands.
        apply_emit(&mut r, &mut h, &view);
        let second = r.diff();
        assert!(second.is_empty(), "unchanged tree must emit zero commands");
    }

    #[test]
    fn spacing_delta_emits_only_root_reset_and_prop() {
        let mut a = vstack![text("ab")].with(|v| { v.spacing(4.0); }).build();
        assign_ids(&mut a, &mut 1);
        let mut h = Harness::new();
        let mut r = QtRenderer::new();
        apply_emit(&mut r, &mut h, &a);
        let _ = r.diff();

        let mut b = vstack![text("ab")].with(|v| { v.spacing(12.0); }).build();
        assign_ids(&mut b, &mut 1);
        apply_emit(&mut r, &mut h, &b);
        let cmds = r.diff();

        assert_eq!(cmds.len(), 2, "only RESET + SET_PROPERTY for the root");
        assert_eq!(cmds[0].kind, Command::RESET_NODE);
        assert_eq!(cmds[0].a, 1);
        assert_eq!(cmds[1].kind, Command::SET_PROPERTY);
        assert_eq!(cmds[1].a, 1);
        assert_eq!(
            (cmds[1].b & 0xFFFF) as u16,
            pathland_core::property_id::SPACING
        );
        assert_eq!(cmds[1].c, 12.0f32.to_bits());
    }

    #[test]
    fn text_delta_emits_only_set_text() {
        let mut a = vstack![text("ab")].build();
        assign_ids(&mut a, &mut 1);
        let mut h = Harness::new();
        let mut r = QtRenderer::new();
        apply_emit(&mut r, &mut h, &a);
        let _ = r.diff();

        let mut b = vstack![text("xy")].build();
        assign_ids(&mut b, &mut 1);
        apply_emit(&mut r, &mut h, &b);
        let cmds = r.diff();

        assert_eq!(cmds.len(), 1);
        assert_eq!(cmds[0].kind, Command::SET_TEXT);
        assert_eq!(cmds[0].a, 2);
    }

    #[test]
    fn deleted_node_emits_delete() {
        let mut a = vstack![text("ab"), text("cd")].build();
        assign_ids(&mut a, &mut 1);
        let mut h = Harness::new();
        let mut r = QtRenderer::new();
        apply_emit(&mut r, &mut h, &a);
        let _ = r.diff();

        let mut b = vstack![text("ab")].build();
        assign_ids(&mut b, &mut 1);
        apply_emit(&mut r, &mut h, &b);
        let cmds = r.diff();

        assert!(
            cmds.iter().any(|c| c.kind == Command::DELETE_NODE && c.a == 3),
            "removed text node 3 is deleted"
        );
        assert!(
            cmds.iter().any(|c| c.kind == Command::REMOVE_CHILD && c.a == 1 && c.b == 3),
            "child 3 removed from root 1"
        );
    }

    #[test]
    fn children_diff_moves_and_appends() {
        // The DSL reorders by position (ids follow tree order), so a "swap"
        // is a text change, not a structural reorder. Exercise the structural
        // delta directly.
        let cmds = children_diff(1, &[2, 3], &[3, 2, 4]);
        assert!(
            cmds.iter().any(|c| c.kind == Command::REMOVE_CHILD && c.a == 1 && c.b == 2),
            "2 moved out"
        );
        assert!(
            cmds.iter().any(|c| c.kind == Command::INSERT_CHILD && c.a == 1 && c.b == 2 && c.c == 1),
            "2 reinserted at index 1"
        );
        assert!(
            cmds.iter().any(|c| c.kind == Command::INSERT_CHILD && c.a == 1 && c.b == 4 && c.c == 2),
            "4 appended at index 2"
        );

        // Identical lists emit nothing.
        assert!(children_diff(1, &[2, 3], &[2, 3]).is_empty());
    }

    #[test]
    fn roots_are_children_of_content_item() {
        let mut view = vstack![text("ab")].build();
        assign_ids(&mut view, &mut 1);
        let mut h = Harness::new();
        let mut r = QtRenderer::new();
        apply_emit(&mut r, &mut h, &view);
        let cmds = r.diff();
        assert!(
            cmds.iter().any(|c| c.kind == Command::INSERT_CHILD && c.a == CONTENT_ITEM && c.b == 1),
            "root 1 is inserted into the content item"
        );
    }
}

// Shared C ABI types between the Rust decode core and the C++ Qt widget layer.
//
// A `PathlandQtCommand` is one delta: Rust produces a batch (mirroring the
// opcode engine's "only changes" discipline) and C++ applies it to the Qt Quick
// scene. This is deliberately a flat struct — the renderer's FFI boundary stays
// a batch of small commands, never a serialized tree.
//
// Inputs flow back the same way: a `PathlandQtEvent` carries one raw input
// (control signal -> C++ -> Rust, which encodes the EVENT opcode and wakes the
// host). The renderer never drains events.
#ifndef PATHLAND_QT_LAYER_H
#define PATHLAND_QT_LAYER_H

#include <stdint.h>
#include <stddef.h>

#ifdef __cplusplus
extern "C" {
#endif

typedef enum PathlandQtCommandKind {
    PLQT_CREATE_NODE = 0,   /* a=id, b=componentType(u16 low)                    */
    PLQT_DELETE_NODE = 1,   /* a=id                                              */
    PLQT_INSERT_CHILD = 2,  /* a=parent, b=child, c=index (u32::MAX = append)    */
    PLQT_REMOVE_CHILD = 3,  /* a=parent, b=child                                 */
    PLQT_MOVE_CHILD = 4,    /* a=parent, b=child, c=newIndex                     */
    PLQT_SET_TEXT = 5,      /* a=id, str=text                                    */
    PLQT_SET_PROPERTY = 6,  /* a=id, b=(valueType<<16)|propertyId, c=value       */
    PLQT_SET_STRING_PROPERTY = 7, /* a=id, b=propertyId, str=value              */
    PLQT_RESET_NODE = 8,    /* a=id — reset renderer-owned style to defaults     */
    PLQT_SET_SCHEME = 9,    /* a=scheme (0 light, 1 dark)                        */
} PathlandQtCommandKind;

typedef struct PathlandQtCommand {
    uint8_t kind;
    uint32_t a;
    uint32_t b;
    uint32_t c;
    uint32_t str_len;
    const char *str;
} PathlandQtCommand;

/* One raw input reported by the Qt layer (C++ -> Rust). */
typedef enum PathlandQtEventKind {
    PLQT_EV_NONE = 0,
    PLQT_EV_POINTER_UP = 1,   /* a control was tapped / pointer released (x,y)   */
    PLQT_EV_VALUE_CHANGED = 2, /* a control's semantic value changed (f32)      */
    PLQT_EV_TEXT_CHANGED = 3, /* a text field's value changed (str)             */
    PLQT_EV_POINTER_DOWN = 4, /* pointer pressed on a listener node (x,y)       */
    PLQT_EV_POINTER_MOVE = 5, /* pointer moved on a listener node (x,y)         */
    PLQT_EV_NAVIGATE_BACK = 6, /* native back request (Escape), global           */
    PLQT_EV_SCHEME_CHANGED = 7, /* platform color scheme changed (value 0/1)     */
} PathlandQtEventKind;

typedef struct PathlandQtEvent {
    uint8_t kind;
    uint32_t node_id;
    float x;
    float y;
    float value;
    uint32_t str_len;
    const char *str;
} PathlandQtEvent;

/* Wake callback into the Rust host: an event was written to the ring; the host
   drains its own event ring (renderer never drains). */
typedef void (*PathlandQtWake)(void *user);
/* Qt timer tick -> Rust pump (drain pending frames), like GTK's idle pump. */
typedef void (*PathlandQtTick)(void *user);
/* A raw input fired (C++ -> Rust): Rust encodes the EVENT opcode + writes it,
   then wakes the host. */
typedef void (*PathlandQtEventFn)(const PathlandQtEvent *ev, void *user);

/* Own the Qt application shell (QGuiApplication + QQuickWindow + engine +
   root item + idle tick timer). `pathland_qt_layer_run` blocks until the
   window closes; `pathland_qt_layer_init` only builds the shell so tests can
   drive `apply` headless without an event loop. */
int pathland_qt_layer_init(PathlandQtWake wake, PathlandQtTick tick,
                           PathlandQtEventFn event_fn, void *user);
int pathland_qt_layer_run(const char *title, int width, int height,
                          PathlandQtWake wake, PathlandQtTick tick,
                          PathlandQtEventFn event_fn, void *user);

/* Apply a batch of delta commands to the Qt Quick scene. */
void pathland_qt_layer_apply(const PathlandQtCommand *cmds, uint32_t count);

/* Reset the whole scene (META::RESET). */
void pathland_qt_layer_reset(void);

/* Quit the event loop (host-initiated shutdown). */
void pathland_qt_layer_quit(void);

/* Test hooks: query the live scene so Rust tests can assert on it. */
uint32_t pathland_qt_layer_apply_count(void);
uint32_t pathland_qt_layer_last_text(char *out, uint32_t cap);
uint32_t pathland_qt_layer_root_child_count(void);
uint32_t pathland_qt_layer_widget_child_count(uint32_t id);
uint32_t pathland_qt_layer_widget_text(uint32_t id, char *out, uint32_t cap);
uint32_t pathland_qt_layer_widget_prop_text(uint32_t id, const char *prop,
                                            char *out, uint32_t cap);
uint32_t pathland_qt_layer_widget_fill(uint32_t id, uint32_t which);
double pathland_qt_layer_widget_preferred(uint32_t id, uint32_t which);
double pathland_qt_layer_widget_size(uint32_t id, uint32_t which);
uint32_t pathland_qt_layer_anchors_fill(uint32_t id);
int pathland_qt_layer_render_once(void);

#ifdef __cplusplus
}
#endif

#endif /* PATHLAND_QT_LAYER_H */

// The C++ Qt Quick shell + widget mapping for `pathland-render-qt`.
//
// Owns the Qt application objects (QGuiApplication / QQuickWindow / QQmlEngine /
// a root Item / the QML-facing Bridge) and applies the Rust delta command batch
// to QML items: create/delete/insert/remove widgets, set text + properties, and
// report control inputs back through the Bridge. The shell is split so tests
// can `init` the scene headless (offscreen) and drive `apply` without entering
// the event loop.
//
// Contract: the renderer never drains events — Rust encodes what the Bridge
// reports and wakes the host. Programmatic value sets suppress echoes, and only
// BINDING_ID/ACTION_ID-gated nodes report interactions (spec/EVENTS.md).

