// The QML-facing bridge: QML controls call its invokables (e.g. a Button's
// `onClicked: bridge.tap(id, x, y)`), and it forwards a `PathlandQtEvent` to
// the Rust host. The host owns the transport + wire encoding; it only needs to
// know "a raw input happened" — and this bridge carries the minimal payload
// (kind + node id + value/text) so Rust can encode the EVENT opcode.
//
// Event guards mirror spec/EVENTS.md: an interaction is only reported when the
// node carries BINDING_ID / ACTION_ID (the "gated" set) and never while the
// renderer itself is setting a value (programmatic echo suppression).
#ifndef PATHLAND_QT_BRIDGE_H
#define PATHLAND_QT_BRIDGE_H

#include <QtCore/QObject>
#include <cstdint>
#include <unordered_set>
#include "pathland_qt.h"

class Bridge : public QObject {
    Q_OBJECT
public:
    explicit Bridge(QObject *parent = nullptr);
    // C++ -> Rust event routing (assigned by the shell).
    PathlandQtEventFn event_fn = nullptr;
    void *user = nullptr;
    // Shared renderer state (owned by qt_layer.cpp).
    std::unordered_set<uint32_t> *gated = nullptr;
    bool *suppress = nullptr;

public slots:
    // Called from QML: `onClicked: bridge.tap(nodeId, x, y)` etc.
    void tap(quint32 nodeId, qreal x, qreal y);
    void valueChanged(quint32 nodeId, qreal value);
    void textChanged(quint32 nodeId, const QString &text);
    // Raw pointer streams from an EVENT_LISTENERS MouseArea (`kind` is a
    // PLQT_EV_POINTER_* value); NOT gated by BINDING_ID — the listener mask
    // already filtered which handlers were attached.
    void pointer(quint32 nodeId, quint32 kind, qreal x, qreal y);
    // Global native back request (Escape) — never node-keyed.
    void navigateBack();
    // Platform color-scheme changed (value 0 = light, 1 = dark).
    void schemeChanged(quint32 scheme);
};

#endif // PATHLAND_QT_BRIDGE_H=== bridge.cpp ===
#include "bridge.h"
#include <QtCore/QString>

namespace {
void fire(Bridge *b, const PathlandQtEvent &ev) {
    // Programmatic echo suppression: the renderer set the value itself.
    if (b->suppress && *b->suppress) {
        return;
    }
    // spec/EVENTS.md guards: only gated nodes report interactions.
    if (b->gated && !b->gated->count(ev.node_id)) {
        return;
    }
    if (b->event_fn) {
        b->event_fn(&ev, b->user);
    }
}
} // namespace

Bridge::Bridge(QObject *parent) : QObject(parent) {}

void Bridge::tap(quint32 nodeId, qreal x, qreal y) {
    PathlandQtEvent ev{};
    ev.kind = PLQT_EV_POINTER_UP;
    ev.node_id = nodeId;
    ev.x = static_cast<float>(x);
    ev.y = static_cast<float>(y);
    fire(this, ev);
}

void Bridge::valueChanged(quint32 nodeId, qreal value) {
    PathlandQtEvent ev{};
    ev.kind = PLQT_EV_VALUE_CHANGED;
    ev.node_id = nodeId;
    ev.value = static_cast<float>(value);
    fire(this, ev);
}

void Bridge::textChanged(quint32 nodeId, const QString &text) {
    const QByteArray bytes = text.toUtf8();
    PathlandQtEvent ev{};
    ev.kind = PLQT_EV_TEXT_CHANGED;
    ev.node_id = nodeId;
    ev.str_len = static_cast<uint32_t>(bytes.size());
    ev.str = bytes.constData();
    fire(this, ev);
}

void Bridge::pointer(quint32 nodeId, quint32 kind, qreal x, qreal y) {
    // Raw pointer streams are gated by the EVENT_LISTENERS mask at attachment
    // time (only the permitted handlers are wired), so they bypass the
    // BINDING_ID gate — any element can report raw inputs (spec/EVENTS.md).
    if (suppress && *suppress) {
        return;
    }
    PathlandQtEvent ev{};
    ev.kind = static_cast<uint8_t>(kind);
    ev.node_id = nodeId;
    ev.x = static_cast<float>(x);
    ev.y = static_cast<float>(y);
    if (event_fn) {
        event_fn(&ev, user);
    }
}

void Bridge::navigateBack() {
    // NAVIGATE is global (never node-keyed), so it is never gated.
    PathlandQtEvent ev{};
    ev.kind = PLQT_EV_NAVIGATE_BACK;
    ev.node_id = 0;
    if (event_fn) {
        event_fn(&ev, user);
    }
}

void Bridge::schemeChanged(quint32 scheme) {
    PathlandQtEvent ev{};
    ev.kind = PLQT_EV_SCHEME_CHANGED;
    ev.node_id = 0;
    ev.value = static_cast<float>(scheme);
    if (event_fn) {
        event_fn(&ev, user);
    }
}

